def parse_json(json_str):
    def parse_number(s, start):
        end = start
        if s[start] in '+-':
            end += 1
        if s[end] == '0':
            end += 1
            while end < len(s) and s[end].isdigit():
                end += 1
        elif s[end].isdigit():
            while end < len(s) and s[end].isdigit():
                end += 1
            if end < len(s) and s[end] in '.eE':
                end += 1
                if s[end] in '+-':
                    end += 1
                if end < len(s) and s[end].isdigit():
                    while end < len(s) and s[end].isdigit():
                        end += 1
        else:
            raise ValueError("Invalid number format")
        return s[start:end], end

    def parse_string(s, start):
        end = start + 1
        while end < len(s) and s[end] != '"':
            if s[end] == '\\':
                end += 1
            end += 1
        if end >= len(s) or s[end] != '"':
            raise ValueError("Unterminated string")
        return s[start:end], end + 1

    def parse_array(s, start):
        result = []
        end = start + 1
        while end < len(s) and s[end] != ']':
            if s[end] == ',':
                end += 1
                continue
            value, end = parse_value(s, end)
            result.append(value)
        if end >= len(s) or s[end] != ']':
            raise ValueError("Unterminated array")
        return result, end + 1

    def parse_object(s, start):
        result = {}
        end = start + 1
        while end < len(s) and s[end] != '}':
            if s[end] == ',':
                end += 1
                continue
            if s[end] != '"':
                raise ValueError("Key must be a string")
            key, end = parse_string(s, end)
            if end >= len(s) or s[end] != ':':
                raise ValueError("Colon expected after key")
            end += 1
            value, end = parse_value(s, end)
            result[key] = value
        if end >= len(s) or s[end] != '}':
            raise ValueError("Unterminated object")
        return result, end + 1

    def parse_value(s, start):
        if s[start] == '[':
            return parse_array(s, start)
        elif s[start] == '{':
            return parse_object(s, start)
        elif s[start] in '+-':
            return parse_number(s, start)
        elif s[start].isdigit():
            return parse_number(s, start)
        elif s[start] == 't':
            return "true", 4
        elif s[start] == 'f':
            return "false", 4
        elif s[start] == 'n':
            return "null", 4
        elif s[start] == '"':
            return parse_string(s, start)
        else:
            raise ValueError("Invalid JSON")

    # Main parsing function for the entire JSON string
    value, end = parse_value(json_str, 0)
    if end != len(json_str):
        raise ValueError("Extra characters at the end of the JSON string")
    return value

