    def parse_array(json_str, pos):
        result = []
        pos += 1  # Skip '['
        while json_str[pos] != ']':
            value = parse_value(json_str, pos)
            result.append(value)
            pos += 1  # Skip ','
        pos += 1  # Skip ']'
        return result

    def parse_string(json_str, pos):
        result = []
        pos += 1  # Skip '"'
        while pos < len(json_str) and json_str[pos] != '"':
            if json_str[pos] == '\\':
                pos += 1  # Skip '\\'
                if json_str[pos] == 'n':
                    result.append('\n')
                elif json_str[pos] == 't':
