    def parse_value():
        if json_str[0] == '"':
            # Parse string
            i = 1
            while i < len(json_str) and json_str[i] != '"':
                i += 1
            i += 1  # Skip closing quote
            return json_str[1:i]
        elif json_str[0] == '[':
            # Parse list
            i = 1
            result = []
            while i < len(json_str) and json_str[i] != ']':
                if json_str[i] == ',':
                    i += 1
                elif json_str[i] == '[':
                    result.append(parse_value())
                elif json_str[i] == '{':
                    result.append(parse_object())
                else:
                    # Parse number
                    j = i
                    while j < len(json_str) and json_str[j].isdigit():
                        j += 1
                    if j > i:
                        result.append(int(json_str[i:j]))
                        i = j
                    else:
                        # Parse float
                        j = i
                        if json_str[j] == '.':
                            j += 1
                        while j < len(json_str) and json_str[j].isdigit():
                            j += 1
                        if j > i:
                            result.append(float(json_str[i:j]))
                            i = j
                        else:
                            raise ValueError("Invalid number format")
            i += 1  # Skip closing bracket
            return result
        elif json_str[0] == '{':
            # Parse object
            i = 1
            result = {}
            while i < len(json_str) and json_str[i] != '}':
                if json_str[i] == ',':
                    i += 1
                elif json_str[i] == '"':
                    # Parse key
                    j = i + 1
                    while j < len(json_str) and json_str[j] != '"':
                        j += 1
                    j += 1  # Skip closing quote
                    key = json_str[i:j]
                    i = j
                    # Parse value
                    value = parse_value()
                    result[key] = value
                else:
                    raise ValueError("Invalid object format")
            i += 1  # Skip closing brace
            return result
        elif json_str[0] == 't':
            # Parse true
            return True
        elif json_str[0] == 'f':
            # Parse false
            return False
        elif json_str[0] == 'n':
            # Parse null
            return None
        else:
            raise ValueError("Invalid JSON format")

    def parse(json_str, stack):
        if json_str[0] == '"':
            # Parse string
            i = 1
            while i < len(json_str) and json_str[i] != '"':
                i += 1
            i += 1  # Skip closing quote
            stack.append(json_str[1:i])
        elif json_str[0] == '[':
            # Parse list
            i = 1
            result = []
            while i < len(json_str) and json_str[i] != ']':
                if json_str[i] == ',':
                    i += 1
                elif json_str[i] == '[':
                    result.append(parse_value())
                elif json_str[i] == '{':
                    result.append(parse_object())
                else:
                    # Parse number
                    j = i
                    while j < len(json_str) and json_str[j].isdigit():
                        j += 1
                    if j > i:
                        result.append(int(json_str[i:j]))
                        i = j
                    else:
                        # Parse float
                        j = i
                        if json_str[j] == '.':
                            j += 1
                        while j < len(json_str) and json_str[j].isdigit():
                            j += 1
                        if j > i:
                            result.append(float(json_str[i:j]))
                            i = j
                        else:
                            raise ValueError("Invalid number format")
                i += 1  # Skip closing bracket
            stack.append(result)
        elif json_str[0] == '{':
            # Parse object
            i = 1
            result = {}
            while i < len(json_str) and json_str[i] != '}':
                if json_str[i] == ',':
                    i += 1
                elif json_str[i] == '"':
                    # Parse key
                    j = i + 1
                    while j < len(json_str) and json_str[j] != '"':
                        j += 1
                    j += 1  # Skip closing quote
                    key = json_str[i:j]
                    i = j
                    # Parse value
                    value = parse_value()
                    result[key] = value
                else:
                    raise ValueError("Invalid object format")
            stack.append(result)
        elif json_str[0] == 't':
            # Parse true
            stack.append(True)
        elif json_str[0] == 'f':
            # Parse false
            stack.append(False)
        elif json_str[0] == 'n':
            # Parse null
            stack.append(None)
        else:
            raise ValueError("Invalid JSON format")

    stack = []
    parse(json_str, stack)
