def parse_json(json_str):
    def parse_value(start_index):
        if json_str[start_index:start_index + 4] == "null":
            return None, start_index + 4
        elif json_str[start_index:start_index + 5] == "true":
            return True, start_index + 5
        elif json_str[start_index:start_index + 6] == "false":
            return False, start_index + 6
        elif json_str[start_index] == '"':
            end_index = json_str.find('"', start_index + 1)
            if end_index == -1:
                raise ValueError("Unmatched quote in JSON string")
            value = json_str[start_index + 1:end_index]
            if value.count('\\') % 2 != 0:
                raise ValueError("Invalid escape sequence in JSON string")
            return value, end_index + 1
        elif json_str[start_index] in "0123456789":
            if json_str[start_index] == '0':
                if start_index + 1 < len(json_str) and json_str[start_index + 1] in "xX":
                    end_index = json_str.find('\'', start_index + 2)
                    if end_index == -1:
                        raise ValueError("Unmatched quote in JSON string")
                    value = int(json_str[start_index + 2:end_index], 16)
                    return value, end_index + 1
                else:
                    end_index = start_index
                    while end_index < len(json_str) and json_str[end_index] in "0123456789":
                        end_index += 1
                    value = int(json_str[start_index:end_index])
                    return value, end_index
