    def parse_object():
        nonlocal i
        if json_str[i] != '{':
            raise ValueError("Expected '{' to start an object")

        i += 1  # Skip '{'
        result = {}
        while i < len(json_str):
            if json_str[i] == '}':
                i += 1  # Skip '}'
                return result
            if i >= len(json_str):
                raise ValueError("Unexpected end of JSON string")
            key = parse_string()
            if i >= len(json_str):
                raise ValueError("Unexpected end of JSON string")
            if json_str[i] != ':':
                raise ValueError("Expected ':' after key")
            i += 1  # Skip ':'
            value = parse_value()
            result[key] = value
            if i >= len(json_str):
                raise ValueError("Unexpected end of JSON string")
            if json_str[i] == ',':
                i += 1  # Skip ','
            else:
                if json_str[i] != '}':
                    raise ValueError("Expected ',' or '}' after value")
                i += 1  # Skip '}'

    def parse_array():
        nonlocal i
        if json_str[i] != '[':
            raise ValueError("Expected '[' to start an array")

        i += 1  # Skip '['
        result = []
        while i < len(json_str):
            if json_str[i] == ']':
                i += 1  # Skip ']'
                return result
            if i >= len(json_str):
                raise ValueError("Unexpected end of JSON string")
            value = parse_value()
            result.append(value)
            if i >= len(json_str):
                raise ValueError("Unexpected end of JSON string")
            if json_str[i] == ',':
                i += 1  # Skip ','
            else:
                if json_str[i] != ']':
                    raise ValueError("Expected ',' or ']' after value")
                i += 1  # Skip ']'

    def parse_string():
        nonlocal i
        if json_str[i] != '"':
            raise ValueError("Expected '\"' to start a string")

        i += 1  # Skip '"'
        result = []
        while i < len(json_str) and json_str[i] != '"':
            if json_str[i] == '\\':
                i += 1  # Skip '\\'
                if i >= len(json_str):
                    raise ValueError("Unexpected end of JSON string")
                c = json_str[i]
                if c in ['"', '\\', '/', 'b', 'f', 'n', 'r', 't']:
                    result.append(c)
                else:
                    raise ValueError(f"Invalid escape sequence '\\{c}'")
                i += 1
            else:
                result.append(json_str[i])
                i += 1
        i += 1  # Skip '"'
        return ''.join(result)

    def parse_number():
        nonlocal i
        start = i
        if json_str[i] in '+-':
