            i += 1
        if i < len(json_str) and json_str[i] in '.eE':
            i += 1
            if json_str[i] not in '0123456789':
                raise ValueError("Invalid number format")
            while i < len(json_str) and json_str[i] in '0123456789':
                i += 1
        return float(json_str[start:i]) if '.' in json_str or 'e' in json_str or 'E' in json_str else int(json_str[start:i])

