        elif state[0] == '[':
            return parse_array(state)
        elif state[0].isdigit() or state[0] in "+-.":
            return parse_number(state)
        elif state[0] == '"':
            return parse_string(state)
        elif state[0] in "trueFalse":
            return parse_boolean(state)
        elif state[0] == 'null':
            return parse_null(state)
        else:
            raise ValueError("Invalid JSON structure")

    def parse_object(state):
        result = {}
        state = state[1:]  # Remove the opening '{'

        while True:
            key = parse_string(state)
            if state[0] != ':':
                raise ValueError("Invalid JSON structure")
            state = state[1:]  # Remove the colon ':'

            value = parse_value(state)
            result[key] = value

            if state[0] == '}':
                state = state[1:]  # Remove the closing '}'
                return result
            elif state[0] != ',':
                raise ValueError("Invalid JSON structure")

            state = state[1:]  # Remove the comma ','

    def parse_array(state):
        result = []
        state = state[1:]  # Remove the opening '['

        while True:
            value = parse_value(state)
            result.append(value)

            if state[0] == ']':
                state = state[1:]  # Remove the closing ']'
                return result
            elif state[0] != ',':
                raise ValueError("Invalid JSON structure")

            state = state[1:]  # Remove the comma ','

    def parse_number(state):
        number = ""
        while state and (state[0].isdigit() or state[0] in "+-." or state[0] in "eE"):
            number += state[0]
            state = state[1:]

        try:
            if "." in number or "+" in number or "-" in number or "e" in number or "E" in number:
                return float(number)
            else:
                return int(number)
        except ValueError:
            raise ValueError("Invalid JSON structure")

    def parse_string(state):
        result = ""
        state = state[1:]  # Remove the opening '"'

        while state and state[0] != '"':
            if state[0] == "\\":
                if state[1] == "n":
                    result += "\n"
                elif state[1] == "r":
                    result += "\r"
                elif state[1] == "t":
                    result += "\t"
                elif state[1] == "b":
                    result += "\b"
                elif state[1] == "f":
                    result += "\f"
                elif state[1] == "u":
