                        raise ValueError("Invalid JSON structure")
                    hex_value = state[2:6]
                    result += chr(int(hex_value, 16))
                    state = state[6:]
                else:
                    result += state[1]
                state = state[2:]
            else:
                result += state[0]
                state = state[1:]

        if state and state[0] == '"':
            state = state[1:]  # Remove the closing '"'
            return result
        else:
            raise ValueError("Invalid JSON structure")

