def parse_json(json_str):
    def parse_value():
        nonlocal json_str  # Declare json_str as nonlocal to allow modification

        if json_str and json_str[0] == '"':
            json_str = json_str[1:]
            i = json_str.find('"')
            if i == -1:
                raise ValueError("Unterminated string constant")
            value = json_str[:i]
            json_str = json_str[i+1:]
            return value
        elif json_str and json_str[0] == '-':
            i = json_str.find('eE')
            if i == -1:
                raise ValueError("Invalid number format")
            value = float(json_str[:i+1])
            json_str = json_str[i+1:]
            return value
        elif json_str and json_str[0] == '[':
            json_str = json_str[1:]
            result = []
            while json_str and json_str[0] != ']':
                value = parse_value()
                result.append(value)
                if json_str and json_str[0] == ',':
                    json_str = json_str[1:]
            json_str = json_str[1:]
            return result
        elif json_str and json_str[0] == '{':
            json_str = json_str[1:]
            result = {}
            while json_str and json_str[0] != '}':
                key = parse_value()
                json_str = json_str[1:]
                if json_str and json_str[0] != ':':
                    raise ValueError("Missing colon in dictionary")
                json_str = json_str[1:]
                value = parse_value()
                result[key] = value
                if json_str and json_str[0] == ',':
                    json_str = json_str[1:]
            json_str = json_str[1:]
            return result
        elif json_str and json_str[0] == 't':
            json_str = json_str[2:]
            if json_str[:3] != 'rue':
                raise ValueError("Invalid boolean value")
            json_str = json_str[3:]
            return True
        elif json_str and json_str[0] == 'f':
            json_str = json_str[3:]
            if json_str[:4] != 'alse':
                raise ValueError("Invalid boolean value")
            json_str = json_str[4:]
            return False
        elif json_str and json_str[0] == 'n':
            json_str = json_str[3:]
            if json_str[:3] != 'ull':
                raise ValueError("Invalid null value")
            json_str = json_str[3:]
            return None
        else:
            # Remove leading whitespace and find the next non-space character
            i = json_str.find(' ')
            if i != -1:
                json_str = json_str[i:]
            try:
                # Try to parse an integer
                value = int(json_str[0])
                json_str = json_str[1:]
                return value
            except ValueError:
                # Try to parse a float
                i = json_str.find('.')
                if i != -1:
                    try:
                        value = float(json_str[:i + 1])
                        json_str = json_str[i + 1:]
                        return value
                    except ValueError:
                        # If neither works, it's an invalid token
                        raise ValueError("Invalid token")
                else:
                    raise ValueError("Invalid token")

    try:
        return parse_value()
    except (ValueError, SyntaxError) as e:
        raise ValueError("JSON parse error: " + str(e))

