    def parse_whitespace(json_str, i):
        while i < len(json_str) and json_str[i].isspace():
            i += 1
        return i

    def parse_number(json_str, i):
        has_sign = False
        has_digit = False
        if json_str[i] in '+-':
            has_sign = True
            i += 1

        while i < len(json_str) and json_str[i].isdigit():
            has_digit = True
            i += 1

        if has_digit and json_str[i] == '.':
            i += 1
            has_digit = False
            while i < len(json_str) and json_str[i].isdigit():
                has_digit = True
                i += 1

        if has_digit and (json_str[i] == 'e' or json_str[i] == 'E'):
            i += 1
            has_sign = False
            if i < len(json_str) and (json_str[i] in '+-'):
                has_sign = True
                i += 1
            has_digit = False
            while i < len(json_str) and json_str[i].isdigit():
                has_digit = True
                i += 1

        if not has_digit:
            raise ValueError("Invalid number")

        if has_sign and (not json_str[i].isdigit() and json_str[i] not in '.,eE'):
            raise ValueError("Invalid number")

        return i

    def parse_string(json_str, i):
        result = []
        escaped = False
        while i < len(json_str):
            if json_str[i] == '\\':
                escaped = True
                i += 1
                if i == len(json_str):
                    raise ValueError("Unterminated escape sequence")
            elif json_str[i] == '"':
                if escaped:
                    result.append('"')
                    escaped = False
                else:
                    break
            else:
                result.append(json_str[i])
            i += 1
        if i == len(json_str) or json_str[i] != '"':
            raise ValueError("Invalid string")

        return ''.join(result), i

    def parse_array(json_str, i):
        result = []
        while i < len(json_str) and json_str[i] != ']':
            value, i = parse_value(json_str, i)
            result.append(value)
            if i < len(json_str) and json_str[i] == ',':
                i += 1
                continue
        if i == len(json_str) or json_str[i] != ']':
            raise ValueError("Invalid array")
        i += 1
        return result, i

    def parse_object(json_str, i):
        result = {}
        while i < len(json_str) and json_str[i] != '}':
            key, i = parse_string(json_str, i)
            if i < len(json_str) and json_str[i] != ':':
                raise ValueError("Invalid key")
            i += 1
            value, i = parse_value(json_str, i)
            result[key] = value
            if i < len(json_str) and json_str[i] == ',':
                i += 1
                continue
        if i == len(json_str) or json_str[i] != '}':
            raise ValueError("Invalid object")
        i += 1
        return result, i

    def parse_value(json_str, i):
        if json_str[i] == '{':
            i += 1
            obj, i = parse_object(json_str, i)
            if i < len(json_str) and json_str[i] != '}':
                raise ValueError("Invalid object")
            i += 1
            return obj, i

        elif json_str[i] == '[':
            i += 1
            arr, i = parse_array(json_str, i)
            if i < len(json_str) and json_str[i] != ']':
                raise ValueError("Invalid array")
            i += 1
            return arr, i

        elif json_str[i] == '"':
            i, value = parse_string(json_str, i)
            return value, i

        elif json_str[i] in '0123456789':
            i = parse_number(json_str, i)
            return int(value), i

        elif json_str[i] in 'true':
            i += 4
            return True, i

        elif json_str[i] in 'false':
            i += 5
            return False, i

        elif json_str[i] in 'null':
            i += 4
            return None, i

        else:
            raise ValueError("Invalid value")

    result, _ = parse_value(json_str, 0)
    return result

